// <diletta-pagination> — a INSTÂNCIA WEB de `design-system-pagination`.
//
// Uma das cinco peças web-NATIVAS do censo: no celular a mesma necessidade se
// resolve por rolagem infinita, que é outra gramática. Não é falta de paridade.
//
// A CONTAGEM ("Exibindo 1-20 de 200") fica FORA: no arquivo ela mora na borda
// inicial da tabela e a paginação na final — dois objetos a mais de 800px de
// distância, e juntá-los obrigaria a peça a atravessar a largura da tabela.
const ALTURA = 30;

const SETA = (dir) =>
  `<svg viewBox="0 0 16 16" aria-hidden="true" focusable="false"
     style="transform:rotate(${dir === 'ant' ? 180 : 0}deg)">
   <path d="M6 3l5 5-5 5" stroke="currentColor" stroke-width="1.5" fill="none"
     stroke-linecap="round" stroke-linejoin="round"/></svg>`;

class DilettaPagination extends HTMLElement {
  static observedAttributes = ['paginas', 'atual', 'janela'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this.addEventListener('click', (e) => {
      const alvo = e.composedPath().find((n) => n.dataset && n.dataset.p !== undefined);
      if (alvo) this.vaiPara(Number(alvo.dataset.p));
    });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  get paginas() { return Math.max(1, Number(this.getAttribute('paginas') || 1)); }
  get atual() { return Math.min(this.paginas, Math.max(1, Number(this.getAttribute('atual') || 1))); }

  vaiPara(p) {
    if (p < 1 || p > this.paginas || p === this.atual) return;
    this.setAttribute('atual', String(p));
    this.dispatchEvent(new CustomEvent('mudou', { detail: { pagina: p }, bubbles: true }));
  }

  /// Os degraus com reticência no meio. A largura sai daqui — não é caixa fixa,
  /// e a ressalva da spec é justamente que no Figma as 22 instâncias têm 270
  /// congelados.
  get degraus() {
    const n = this.paginas, a = this.atual, j = Number(this.getAttribute('janela') || 1);
    const dentro = new Set([1, n, a]);
    for (let k = 1; k <= j; k++) { dentro.add(a - k); dentro.add(a + k); }
    const vis = [...dentro].filter((p) => p >= 1 && p <= n).sort((x, y) => x - y);
    const out = [];
    for (let i = 0; i < vis.length; i++) {
      if (i && vis[i] - vis[i - 1] > 1) out.push('…');
      out.push(vis[i]);
    }
    return out;
  }

  render() {
    const a = this.atual, n = this.paginas;
    const botao = (p, conteudo, rotulo, off) =>
      `<button class="d ${off ? 'off' : ''}" ${off ? 'disabled' : `data-p="${p}"`}
        type="button" aria-label="${rotulo}">${conteudo}</button>`;

    const numeros = this.degraus.map((d) => d === '…'
      ? '<span class="rec" aria-hidden="true">…</span>'
      : `<button class="d ${d === a ? 'atual' : ''}" data-p="${d}" type="button"
           ${d === a ? 'aria-current="page"' : ''}
           aria-label="Página ${d}">${d}</button>`).join('');

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline-block; }
        nav { display: inline-flex; align-items: center; gap: 4px; height: ${ALTURA}px; }
        .d {
          min-width: ${ALTURA}px; height: ${ALTURA}px; border-width: 0; border-radius: 999px;
          background: none; color: var(--cps-fg); font: inherit; cursor: pointer;
          display: inline-flex; align-items: center; justify-content: center;
        }
        .d svg { width: 14px; height: 14px; }
        /* Extremo desabilitado CONTINUA no desenho: controle que some move todos
           os outros, e quem ia clicar em "2" clica em "3". */
        .d.off { color: var(--cps-textDisabled); cursor: default; }
        .d.atual { background: var(--cps-primary); color: var(--cps-onPrimary); }
        .rec { color: var(--cps-textDisabled); padding: 0 4px; }
        .d:focus-visible { outline: 3px solid var(--cps-primary); outline-offset: 2px; }
      </style>
      <nav part="nav" aria-label="${this.getAttribute('rotulo') || 'Paginação'}">
        ${botao(a - 1, SETA('ant'), 'Página anterior', a === 1)}
        ${numeros}
        ${botao(a + 1, SETA('prox'), 'Próxima página', a === n)}
      </nav>`;
  }
}

customElements.define('diletta-pagination', DilettaPagination);
export { DilettaPagination, ALTURA };
